import{z as l,x as d,o as E,c as i,q as B,j as t,D as a,d as o,s as n,S as A,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"用户/内核分裂","description":"","frontmatter":{"title":"用户/内核分裂","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/user-kernel-split.md","filePath":"cs/user-kernel-split.md","lastUpdated":1791413859000}'),p={name:"cs/user-kernel-split.md"};function c(m,e,u,C,D,_){const s=d("Mermaid");return E(),i("div",null,[e[2]||(e[2]=B('<h1 id="用户-内核分裂" tabindex="-1">用户/内核分裂 <a class="header-anchor" href="#用户-内核分裂" aria-label="Permalink to &quot;用户/内核分裂&quot;">​</a></h1><div class="epigraph"><p>每个进程的虚空间常被切成用户一半与内核一半；系统调用不必换页表根，只需切特权。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems；Bovet and Cesati, Understanding the Linux Kernel 整理</footer></div><p><a href="/cs/addrspace-layout">上一课</a>已画出文本、数据、堆、栈，并点到「内核常在高半」。<a href="/cs/kernel-user">内核与用户态</a>讲的是特权门，不是这张图怎么切。<a href="/cs/paging-vm">分页</a>已能把任意虚页标成用户不可访问。缺口是<strong>分裂本身</strong>：为何内核映射进每个进程，用户指针与内核指针如何共存。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>系统调用要读用户缓冲、要写页表，若内核活在另一套地址空间，每次陷入都换页表根，<a href="/cs/tlb-translate">TLB</a> 全作废。经典 Unix/Linux 选择：同一套页表里，高地址是内核，页表项清掉用户可访问位；低地址是该进程用户空间。缺口不是再导页表格式，而是约定这道分界，以及内核如何安全地解引用用户指针。</p><p>本课不把每种架构的分界数字当考纲。</p><p><span class="marginnote">32 位曾用 3G/1G；64 位用 canonical 空洞把用户与内核远远分开。对象仍是：内核代码在每个进程里都有翻译，用户走不到那些页。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬件用页表项的用户位执行分裂：用户态访问内核虚地址立即故障。<a href="/cs/syscall-path">系统调用路径</a>上，内核带着自己的指针跑，同时用 <code>copy_from_user</code> / <code>copy_to_user</code> 触及用户缓冲——那些函数先检查指针落在用户区间，再在故障时把缺页或坏地址变成错误码，而不是内核 oops。</p>',9)),(E(),t(A,null,{default:a(()=>[n(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%E8%99%9A%E5%8C%BA%E9%97%B4%22%5D%20--%3E%20SYSCALL%5B%22%E9%99%B7%E5%85%A5%3A%20%E4%BB%8D%E6%AD%A4%E9%A1%B5%E8%A1%A8%22%5D%0A%20%20K%5B%22%E5%86%85%E6%A0%B8%E8%99%9A%E5%8C%BA%E9%97%B4%22%5D%20--%3E%20SYSCALL%0A%20%20SYSCALL%20--%3E%20COPY%5B%22copy_from_user%22%5D%0A%20%20COPY%20--%3E%20CHK%5B%22%E8%B6%8A%E7%95%8C%E5%88%99%E5%A4%B1%E8%B4%A5%2C%20%E4%B8%8D%E5%86%99%E5%86%85%E6%A0%B8%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r("h2",{id:"机制",tabindex:"-1"},[o("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=r("p",null,"分裂的两条「越界」路径结局完全不同——用户碰内核地址当场死，内核碰坏用户地址优雅报错：",-1)),(E(),t(A,null,{default:a(()=>[n(s,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20UL%5B%22%E7%94%A8%E6%88%B7%E6%80%81%20load%20%E5%86%85%E6%A0%B8%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20PF1%5B%22%E9%A1%B5%E8%A1%A8%E9%A1%B9%E6%97%A0%E7%94%A8%E6%88%B7%E4%BD%8D%2C%20%E8%A7%A6%E5%8F%91%E7%BC%BA%E9%A1%B5%22%5D%0A%20%20PF1%20--%3E%20Q1%7B%22%E6%95%85%E9%9A%9C%E5%8F%91%E7%94%9F%E5%9C%A8%E5%86%85%E6%A0%B8%E6%80%81%3F%22%7D%0A%20%20Q1%20--%3E%7C%E5%90%A6%2C%20%E7%94%A8%E6%88%B7%E8%87%AA%E5%B7%B1%E9%97%AF%E7%9A%84%7C%20SIG%5B%22%E5%88%86%E5%8F%91%20SIGSEGV%2C%20%E8%BF%9B%E7%A8%8B%E7%BB%88%E6%AD%A2%22%5D%0A%20%20KC%5B%22%E5%86%85%E6%A0%B8%E6%89%A7%E8%A1%8C%20copy_from_user(%E7%94%A8%E6%88%B7%E6%8C%87%E9%92%88)%22%5D%20--%3E%20BAD%7B%22%E6%8C%87%E9%92%88%E5%9D%8F%20%2F%20%E9%A1%B5%E6%9C%AA%E6%98%A0%E5%B0%84%3F%22%7D%0A%20%20BAD%20--%3E%7C%E5%90%A6%7C%20OK%5B%22%E6%8B%B7%E8%B4%9D%E6%88%90%E5%8A%9F%2C%20%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20BAD%20--%3E%7C%E6%98%AF%7C%20FIX%5B%22%E8%B7%B3%E5%88%B0%20fixup%20%E4%BB%A3%E7%A0%81%22%5D%0A%20%20FIX%20--%3E%20RET%5B%22%E8%BF%94%E5%9B%9E%20-EFAULT%20%E7%BB%99%E8%B0%83%E7%94%A8%E6%96%B9%22%5D%0A%20%20RET%20--%3E%20CONT%5B%22%E8%BF%9B%E7%A8%8B%E6%B4%BB%E7%9D%80%2C%20%E7%94%B1%E5%AE%83%E8%87%AA%E5%B7%B1%E5%A4%84%E7%90%86%E9%94%99%E8%AF%AF%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=B('<p>分裂让内核成为「始终可见的那一半」：中断、系统调用、缺页入口都能用同一套内核符号。用户隔离仍靠<a href="/cs/paging-vm">分页</a>的用户位与各进程不同的低半页表，不靠再发明一套环。与特权课的分工：环决定「能不能执行 <code>csrrw satp</code>」；分裂决定「用户 load 能不能碰到内核数据」。</p><p>后课的 <code>brk</code> 只移动用户堆的上限，碰不到内核分界。</p><p><span class="marginnote"><code>copy_from_user</code> 可以翻译成「自带安检的 memcpy」：先查指针确实落在用户区间，再把拷贝路径上每条访存指令配一个故障修复点——一旦踩空，不崩内核，只把「这地址不行」翻译成 <code>-EFAULT</code> 返回。普通 <code>memcpy</code> 没有这套保险，内核里直接用它等于把 panic 权交给用户。</span></p><p><span class="marginnote">数字实例：32 位 Linux 的分界在 <code>0xC0000000</code>。进程 A 看见指针 <code>0xC0001000</code> 时它是「内核的」；而同一虚地址在进程 B 的页表里映射的也是同一个内核页——内核那半是全员共享的同一份翻译，只有低半才是各进程私有。这正解释了「系统调用不必换页表根」。</span></p><p><span class="marginnote">常见误区：初学者容易以为每次系统调用都要切换页表、TLB 全清。实际上经典设计只切特权级，页表根不动，内核高半的翻译照旧有效——这正是把内核映射进每个进程的动机。KPTI 那类隔离加固才把内核从用户页表里拿掉，代价是多一次切换。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 KPTI 的侧信道对策全文，只承认：把内核从用户页表里拿掉会多一次页表切换，换 TLB 隔离。也不把模块加载的内核虚地址分配写完。用户/内核指针在类型上应分开；教学上记住「用户指针必须经拷贝路径」。</p><p>后课默认：合法用户虚区间在分界以下（或 canonical 用户半）。堆如何向高处申请，下一课 <code>brk</code> 与堆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内核映射进每个进程的高半，陷入少换页表根。</li><li>用户位执行分裂；用户缓冲经拷贝路径进入内核。</li><li>堆上限如何移动是 <code>brk</code> 的缺口。</li><li>出处：Tanenbaum <em>MOS</em>；Bovet and Cesati, <em>ULK</em>；Love, <em>Linux Kernel Development</em>。</li></ul>',10))])}const T=l(p,[["render",c]]);export{f as __pageData,T as default};
